// Enhanced CoinPaprika API Tool for n8n - Crypto Trading Analysis
// This tool fetches comprehensive cryptocurrency data without requiring an API key
// Supports multiple coins, global market data, historical charts, and trending analysis

// --- CONFIGURATION ---
const item = items[0];
const input = item.json;

// Determine operation mode
const mode = input.mode || 'single'; // 'single', 'multiple', 'global', 'trending'
const cryptoSymbols = input.symbols || (input.symbol ? [input.symbol] : ['BTC', 'QUBIC']); // Support array of symbols
const includeCharts = input.includeCharts !== false; // Default true
const includeGlobal = input.includeGlobal !== false; // Default true

// --- HELPER FUNCTIONS ---
const formatNumber = (num, decimals = 2) => {
  if (num >= 1e9) return `$${(num / 1e9).toFixed(2)}B`;
  if (num >= 1e6) return `$${(num / 1e6).toFixed(2)}M`;
  if (num >= 1e3) return `$${(num / 1e3).toFixed(2)}K`;
  return `$${num.toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals })}`;
};

const formatPrice = (price) => {
  if (price < 0.00001) return `$${price.toFixed(10)}`;
  if (price < 0.01) return `$${price.toFixed(8)}`;
  if (price < 1) return `$${price.toFixed(6)}`;
  if (price < 100) return `$${price.toFixed(4)}`;
  return `$${price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
};

const getChangeEmoji = (change) => {
  if (change > 10) return '🚀';
  if (change > 5) return '📈';
  if (change > 0) return '⬆️';
  if (change < -10) return '💥';
  if (change < -5) return '📉';
  if (change < 0) return '⬇️';
  return '➡️';
};

const getTrendAnalysis = (change24h, change7d, volume24h, marketCap) => {
  let trend = 'neutral';
  let signal = 'HOLD';
  let confidence = 0;

  // Analyze trend
  if (change24h > 10 && change7d > 15) {
    trend = 'strongly bullish';
    signal = 'STRONG BUY';
    confidence = 85;
  } else if (change24h > 5 && change7d > 5) {
    trend = 'bullish';
    signal = 'BUY';
    confidence = 70;
  } else if (change24h < -10 && change7d < -15) {
    trend = 'strongly bearish';
    signal = 'SELL';
    confidence = 85;
  } else if (change24h < -5 && change7d < -5) {
    trend = 'bearish';
    signal = 'WEAK SELL';
    confidence = 60;
  } else if (Math.abs(change24h) < 2 && Math.abs(change7d) < 5) {
    trend = 'consolidating';
    signal = 'HOLD';
    confidence = 50;
  }

  // Volume analysis
  const volumeToMcap = (volume24h / marketCap) * 100;
  const liquidityScore = volumeToMcap > 10 ? 'high' : volumeToMcap > 5 ? 'medium' : 'low';

  return { trend, signal, confidence, liquidityScore, volumeToMcap };
};

// --- MAIN DATA FETCHING ---
const results = {
  timestamp: new Date().toISOString(),
  data_source: 'CoinPaprika API',
  coins: [],
  global_market: null,
  trending_coins: null,
  market_analysis: null,
  emergency_protocol: null
};

try {
  // Step 1: Fetch Global Market Data
  if (includeGlobal) {
    try {
      const globalData = await this.helpers.request('https://api.coinpaprika.com/v1/global');
      results.global_market = {
        total_market_cap: formatNumber(globalData.market_cap_usd),
        total_market_cap_raw: globalData.market_cap_usd,
        total_volume_24h: formatNumber(globalData.volume_24h_usd),
        total_volume_24h_raw: globalData.volume_24h_usd,
        bitcoin_dominance: `${globalData.bitcoin_dominance_percentage.toFixed(2)}%`,
        cryptocurrencies_number: globalData.cryptocurrencies_number,
        market_cap_change_24h: globalData.market_cap_change_24h,
        volume_24h_change_24h: globalData.volume_24h_change_24h,
        last_updated: globalData.last_updated
      };

      // Determine if Emergency Protocol should trigger
      if (globalData.market_cap_change_24h < -15) {
        const severity = globalData.market_cap_change_24h < -30 ? 'extreme' : 'moderate';
        results.emergency_protocol = {
          triggered: true,
          market_drop: `${globalData.market_cap_change_24h.toFixed(2)}%`,
          severity: severity,
          recommendation: severity === 'extreme' 
            ? 'EXTREME CAUTION: Watch market closely, consider reducing positions. Risk of black swan event, death spirals, or dead cat bounces.'
            : 'OPPORTUNITY: Consider buying the dip, but maintain stop-losses. Market correction in progress.',
          warning_level: severity === 'extreme' ? '🚨🚨🚨' : '⚠️'
        };
      }
    } catch (error) {
      console.error("Error fetching global market data:", error.message);
      results.global_market = { error: "Could not fetch global market data" };
    }
  }

  // Step 2: Get coin list for ID lookup
  const allCoins = await this.helpers.request('https://api.coinpaprika.com/v1/coins');

  // Step 3: Process each requested cryptocurrency
  for (const symbol of cryptoSymbols) {
    if (!symbol) continue;

    // Find coin ID
    const coinInfo = allCoins.find(c => c.symbol.toUpperCase() === symbol.toUpperCase());
    if (!coinInfo) {
      results.coins.push({
        symbol: symbol,
        error: `Coin not found on CoinPaprika`
      });
      continue;
    }

    const coinId = coinInfo.id;

    // Fetch comprehensive ticker data
    try {
      const tickerData = await this.helpers.request(`https://api.coinpaprika.com/v1/tickers/${coinId}`);
      const quote = tickerData.quotes.USD;

      // Perform trend analysis
      const analysis = getTrendAnalysis(
        quote.percent_change_24h,
        quote.percent_change_7d,
        quote.volume_24h,
        quote.market_cap
      );

      // Prepare coin data
      const coinData = {
        // Basic Info
        name: tickerData.name,
        symbol: tickerData.symbol,
        rank: tickerData.rank,

        // Price Data
        price: quote.price,
        price_formatted: formatPrice(quote.price),
        ath_price: quote.ath_price,
        ath_date: quote.ath_date,
        percent_from_ath: ((quote.price - quote.ath_price) / quote.ath_price * 100).toFixed(2),

        // Market Data
        market_cap: quote.market_cap,
        market_cap_formatted: formatNumber(quote.market_cap),
        volume_24h: quote.volume_24h,
        volume_24h_formatted: formatNumber(quote.volume_24h),
        volume_24h_change_24h: quote.volume_24h_change_24h,

        // Supply Data
        circulating_supply: tickerData.circulating_supply,
        total_supply: tickerData.total_supply,
        max_supply: tickerData.max_supply,

        // Percentage Changes with Emojis
        percent_change_15m: quote.percent_change_15m,
        percent_change_30m: quote.percent_change_30m,
        percent_change_1h: quote.percent_change_1h,
        percent_change_6h: quote.percent_change_6h,
        percent_change_12h: quote.percent_change_12h,
        percent_change_24h: quote.percent_change_24h,
        percent_change_7d: quote.percent_change_7d,
        percent_change_30d: quote.percent_change_30d,
        percent_change_1y: quote.percent_change_1y,

        // Formatted changes with emojis
        change_24h_display: `${quote.percent_change_24h > 0 ? '+' : ''}${quote.percent_change_24h.toFixed(2)}% ${getChangeEmoji(quote.percent_change_24h)}`,
        change_7d_display: `${quote.percent_change_7d > 0 ? '+' : ''}${quote.percent_change_7d.toFixed(2)}% ${getChangeEmoji(quote.percent_change_7d)}`,

        // Analysis
        trend_analysis: analysis,

        // Beta coefficient (volatility measure)
        beta_value: tickerData.beta_value,

        // Metadata
        last_updated: tickerData.last_updated,
        paprika_url: `https://coinpaprika.com/coin/${coinId}/`
      };

      // Fetch OHLCV data for charts (last 7 days)
      if (includeCharts) {
        try {
          const endDate = new Date().toISOString().split('T')[0];
          const startDate = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
          const ohlcvData = await this.helpers.request(
            `https://api.coinpaprika.com/v1/coins/${coinId}/ohlcv/historical?start=${startDate}&end=${endDate}`
          );

          if (ohlcvData && ohlcvData.length > 0) {
            coinData.chart_data = {
              period: '7d',
              data_points: ohlcvData.length,
              high_7d: Math.max(...ohlcvData.map(d => d.high)),
              low_7d: Math.min(...ohlcvData.map(d => d.low)),
              avg_volume_7d: ohlcvData.reduce((sum, d) => sum + d.volume, 0) / ohlcvData.length,
              volatility_7d: ((Math.max(...ohlcvData.map(d => d.high)) - Math.min(...ohlcvData.map(d => d.low))) / Math.min(...ohlcvData.map(d => d.low)) * 100).toFixed(2),
              price_history: ohlcvData.map(d => ({
                date: d.time_open.split('T')[0],
                open: d.open,
                high: d.high,
                low: d.low,
                close: d.close,
                volume: d.volume
              }))
            };
          }
        } catch (chartError) {
          console.error(`Error fetching chart data for ${symbol}:`, chartError.message);
          coinData.chart_data = { error: "Could not fetch historical data" };
        }
      }

      results.coins.push(coinData);

    } catch (error) {
      console.error(`Error fetching data for ${symbol}:`, error.message);
      results.coins.push({
        symbol: symbol,
        error: `Failed to fetch ticker data: ${error.message}`
      });
    }
  }

  // Step 4: Fetch Trending Coins (Top Gainers)
  if (mode === 'trending' || includeGlobal) {
    try {
      const allTickers = await this.helpers.request('https://api.coinpaprika.com/v1/tickers?limit=100');

      // Find top gainers and losers
      const topGainers = allTickers
        .sort((a, b) => b.quotes.USD.percent_change_24h - a.quotes.USD.percent_change_24h)
        .slice(0, 5)
        .map(coin => ({
          name: coin.name,
          symbol: coin.symbol,
          price: formatPrice(coin.quotes.USD.price),
          change_24h: `${coin.quotes.USD.percent_change_24h.toFixed(2)}% ${getChangeEmoji(coin.quotes.USD.percent_change_24h)}`,
          volume: formatNumber(coin.quotes.USD.volume_24h),
          market_cap: formatNumber(coin.quotes.USD.market_cap)
        }));

      const topLosers = allTickers
        .sort((a, b) => a.quotes.USD.percent_change_24h - b.quotes.USD.percent_change_24h)
        .slice(0, 5)
        .map(coin => ({
          name: coin.name,
          symbol: coin.symbol,
          price: formatPrice(coin.quotes.USD.price),
          change_24h: `${coin.quotes.USD.percent_change_24h.toFixed(2)}% ${getChangeEmoji(coin.quotes.USD.percent_change_24h)}`,
          volume: formatNumber(coin.quotes.USD.volume_24h),
          market_cap: formatNumber(coin.quotes.USD.market_cap)
        }));

      results.trending_coins = {
        top_gainers: topGainers,
        top_losers: topLosers,
        most_volatile: allTickers
          .sort((a, b) => Math.abs(b.quotes.USD.percent_change_24h) - Math.abs(a.quotes.USD.percent_change_24h))
          .slice(0, 5)
          .map(coin => ({
            name: coin.name,
            symbol: coin.symbol,
            volatility: `${Math.abs(coin.quotes.USD.percent_change_24h).toFixed(2)}%`
          }))
      };
    } catch (error) {
      console.error("Error fetching trending coins:", error.message);
      results.trending_coins = { error: "Could not fetch trending data" };
    }
  }

  // Step 5: Generate Market Analysis Summary
  if (results.coins.length > 0) {
    const avgChange24h = results.coins.reduce((sum, coin) => sum + (coin.percent_change_24h || 0), 0) / results.coins.length;
    const avgChange7d = results.coins.reduce((sum, coin) => sum + (coin.percent_change_7d || 0), 0) / results.coins.length;

    results.market_analysis = {
      coins_analyzed: results.coins.length,
      average_change_24h: `${avgChange24h.toFixed(2)}%`,
      average_change_7d: `${avgChange7d.toFixed(2)}%`,
      market_sentiment: avgChange24h > 5 ? 'Bullish 🐂' : avgChange24h < -5 ? 'Bearish 🐻' : 'Neutral 😐',
      recommendation_summary: avgChange7d < -15 ? 'Market correction - Consider buying quality assets' : 
                             avgChange7d > 15 ? 'Overbought conditions - Take profits on winners' : 
                             'Stable market - Focus on fundamentals'
    };
  }

} catch (error) {
  console.error("Critical error in CoinPaprika tool:", error.message);
  results.error = `Critical error: ${error.message}`;
}

// Return comprehensive results
item.json = results;
return item;

